import { useEffect, useState } from "react";
import { io } from "socket.io-client";
import "./AdminDashboard.css";

const socket = io("http://localhost:5000");

function AdminDashboard() {

  const [queues, setQueues] = useState([]);

  const fetchQueues = async () => {
    const res = await fetch("http://localhost:5000/api/queue/all");
    const data = await res.json();
    setQueues(data);
  };

  useEffect(() => {
    fetchQueues();
    socket.on("queueUpdated", fetchQueues);
    return () => socket.off("queueUpdated", fetchQueues);
  }, []);

  const confirmOP = async (id) => {
    await fetch(`http://localhost:5000/api/queue/confirm/${id}`, {
      method: "PUT"
    });
  };

  const completeOP = async (id) => {
    await fetch(`http://localhost:5000/api/queue/complete/${id}`, {
      method: "DELETE"
    });
  };

  return (

    <div className="admin-layout">

      {/* SIDEBAR */}
      <div className="sidebar">

        <h1>HealSync</h1>

        <p>Admin Panel</p>

        <div className="menu">
          <div>Dashboard</div>
          <div>Patients</div>
          <div>Queue</div>
        </div>

      </div>

      {/* MAIN CONTENT */}
      <div className="main">

        {/* HEADER */}
        <div className="topbar">

          <h2>Hospital Queue Dashboard</h2>

          <div className="stats">

            <div className="card">
              <h3>{queues.length}</h3>
              <p>Total OP</p>
            </div>

            <div className="card">
              <h3>{queues.filter(q => q.status === "InQueue").length}</h3>
              <p>In Queue</p>
            </div>

            <div className="card">
              <h3>{queues.filter(q => q.status === "Waiting").length}</h3>
              <p>Waiting</p>
            </div>

          </div>

        </div>

        {/* TABLE */}
        <div className="table">

          <div className="row head">
            <span>Name</span>
            <span>Department</span>
            <span>Status</span>
            <span>Actions</span>
          </div>

          {queues.map((q) => (

            <div className="row" key={q._id}>

              <span>{q.patientName}</span>
              <span>{q.department}</span>

              <span className={`status ${q.status}`}>
                {q.status}
              </span>

              <span className="actions">

                {q.status === "Waiting" && (
                  <button className="confirm" onClick={() => confirmOP(q._id)}>
                    Confirm
                  </button>
                )}

                <button className="delete" onClick={() => completeOP(q._id)}>
                  Complete
                </button>

              </span>

            </div>

          ))}

        </div>

      </div>

    </div>

  );

}

export default AdminDashboard;
